// Each function tests an optional member of the record it is given for
// undefined in one of the ways JavaScript code does, then calls a method on
// it. The checker types the member `any` and cannot use the test.
export function byTernary(row) {
  return row.marks === undefined ? "-" : row.marks.join("+");
}
export function byEarlyReturn(row) {
  if (row.marks === undefined) return "-";
  return row.marks.join("+");
}
export function byLocal(row) {
  const marks = row.marks;
  if (marks === undefined) return "-";
  return marks.join("+");
}
export function byLooseNull(row) {
  return row.marks == null ? "-" : row.marks.join("+");
}
export function byTruthiness(row) {
  return row.marks ? row.marks.join("+") : "-";
}
export function byTypeof(row) {
  return typeof row.marks === "undefined" ? "-" : row.marks.join("+");
}
export function byElse(row) {
  let text;
  if (row.marks === undefined) {
    text = "-";
  } else {
    text = row.marks.join("+");
  }
  return text;
}
export function inLoop(rows) {
  const out = [];
  for (const row of rows) {
    if (row.marks === undefined) continue;
    out.push(row.marks.join("+"));
  }
  return out.join("|");
}
export function inClosure(row) {
  if (row.marks === undefined) return "-";
  const marks = row.marks;
  return [1, 2].map((n) => marks.join(String(n))).join("|");
}
export function ratio(row) {
  return row.ratio === undefined ? "-" : row.ratio.toFixed(1);
}
export function ratioByChain(row) {
  return String(row.ratio?.toFixed(2));
}
export function seen(row) {
  if (!row.seen) return "-";
  return String(row.seen.has("a")) + row.seen.size;
}
// Writes through the narrowed member reach the caller's array.
export function addMark(row, mark) {
  if (row.marks === undefined) return 0;
  row.marks.push(mark);
  return row.marks.length;
}
// No test at all: JavaScript throws when the member is missing.
export function unguarded(row) {
  return row.marks.join("+");
}
// A parameter that is itself `string | undefined` at the call.
export function shout(text) {
  return text === undefined ? "-" : text.toUpperCase();
}
